VALUES ('00000000-0000-0000-0000-000000000904'::uuid, 'ToolResolver', '# Task
Select the best matching tool(s) for the user''s intent. Return one entry per distinct intent.

# Available tools
{{ ctx.meta.available_tools | tojson }}

# Intent-to-method mapping
- When the user wants to CREATE, REGISTER, ADD, RECORD, or INSERT something new → prefer tools with method POST.
- When the user wants to LIST, VIEW, SHOW, SEARCH, or CONSULT existing data → prefer tools with method GET.
- Match the user''s ACTION VERB to the correct HTTP method. Do NOT use a GET/list tool when the user clearly wants to create or register.

# Constraints
- selected_tool must reference a tool from available_tools by name and tool_config_id.
- confidence between 0 and 1.
- intent_type: "query" for GET tools, "command" for POST/PUT/PATCH/DELETE tools.', '{"additionalProperties": false, "properties": {"result": {"items": {"additionalProperties": false, "properties": {"confidence": {"maximum": 1, "minimum": 0, "type": "number"}, "intent_type": {"enum": ["query", "command", "conversation"], "type": "string"}, "selected_tool": {"additionalProperties": false, "properties": {"name": {"type": "string"}, "tool_config_id": {"type": "string"}}, "required": ["name", "tool_config_id"], "type": "object"}}, "required": ["intent_type", "selected_tool", "confidence"], "type": "object"}, "type": "array"}}, "required": ["result"], "type": "object"}'::jsonb, 1, 'd7fc658b8392b27c3ce20b89e2b7ee8a198c2a11c2a4e8e9c92826ef32356294', TRUE, 'Prompt for ToolResolver', 'system', '2026-08-19 12:56:17.933232+00:00', '2026-08-19 12:56:17.933232+00:00')
