VALUES ('6c02d705-9ead-4c13-91ed-10fb8fb0af30'::uuid, '00000000-0000-0000-0000-000000000100'::uuid, '00000000-0000-0000-0000-000000001401'::uuid, 'tool_catalog', 'tool_catalog', 'e4d7dd369c83fcf50c43c7f987f986999af801f615bff0f5e3414ab0557adf12', 'Campos aceites ao registar uma despesa: amount (valor gasto, numero), description (descricao curta do gasto), currency (moeda ISO como BRL, EUR, USD), category (categoria: comida, transporte, saude, lazer), occurred_on (data no formato YYYY-MM-DD; ''ontem'' e o dia anterior), payment_method (PIX, cartao, dinheiro, transferencia), account_label (nome da conta, por exemplo ''conta PF do Santander''). Apenas amount e description sao obrigatorios. Nunca inventar valores.', 'create_expense.v1.body', 'COMPLETED', 1, NULL, '2026-08-19 12:56:14.786353+00:00', '2026-08-19 12:56:15.171020+00:00', '{"category": "TOOL_CATALOG", "cluster": "request_body", "method": "POST", "operation_id": "create_expense", "path": "/expenses", "tool_config_id": "00000000-0000-0000-0000-000000000501", "tool_id": "00000000-0000-0000-0000-000000000500", "tool_intent": "command", "tool_name": "create_expense"}'::jsonb, '2026-08-19 12:56:14.777683+00:00', '2026-08-19 12:56:15.172379+00:00')
